import{_ as e,a as o,b as a,c as r}from"./chunks/spp_polozky4.BMlxLrUn.js";import{_ as n}from"./chunks/spp_polozky3.BRDJgjmN.js";import{_ as s,o as i,c,aa as l}from"./chunks/framework.BAs_AphD.js";const _=JSON.parse('{"title":"Entering Contractor Work Statements","description":"","frontmatter":{"title":"Entering Contractor Work Statements","wiki":"en:performedworks:contractor_actions"},"headers":[],"relativePath":"en/performedworks/contractor_actions.md","filePath":"en/performedworks/contractor_actions.md","lastUpdated":1794388980000}'),p={name:"en/performedworks/contractor_actions.md"};function h(u,t,d,m,g,f){return i(),c("div",null,[...t[0]||(t[0]=[l('<h1 id="entering-contractor-work-statements" tabindex="-1">Entering Contractor Work Statements <a class="header-anchor" href="#entering-contractor-work-statements" aria-label="Permalink to &quot;Entering Contractor Work Statements&quot;">​</a></h1><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>A user with the Contractor Works Proposal permission can edit the Proposed Quantity and Proposed Price columns if the Measurement Report is in the Draft status or does not yet exist for the given period. Values can be entered by typing a number directly into the quantity or amount column.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Consumption can also be entered as a percentage. If the entered number is followed by the &quot;<strong>%</strong>&quot; or &quot;<strong>p</strong>&quot; symbol, the entered number is interpreted as a percentage and converted to a quantity.</p><p>Consumption can also be entered in bulk, as described in a separate section of the Help.</p></div><img src="'+e+'" alt="" width="1200" loading="lazy"><p>Once the work statement proposal for the given period has been completed, the contractor submits the Measurement Report to the client for approval using the following button:</p><figure class="shot" style="--w:200px;"><img src="'+o+'" alt="" width="200" loading="lazy"></figure><p>This also makes the item status, Invoiced Quantity, and Invoiced Price columns visible to the contractor. These values are read-only for the contractor and are provided for information only.</p><h2 id="approval" tabindex="-1">Approval <a class="header-anchor" href="#approval" aria-label="Permalink to &quot;Approval&quot;">​</a></h2><p>The Client Representative can change item statuses in several ways:</p><ul><li><p>Individually by selecting a status from the list (any status from the list can be selected).</p></li><li><p>Individually using keyboard shortcuts. The shortcuts differ depending on the language version. The following key combinations can be used in the Czech and Slovak versions:</p></li></ul><figure class="shot" style="--w:20px;"></figure><p>Approved Alt + S Rejected Alt + X In Negotiation Alt + V Change Alt + Z Draft Alt + N</p><ul><li><p>In bulk for selected items (the procedure is described in the &quot;Contractor SPP Window, Bulk Operations&quot; section of the Help).</p></li><li><p>By changing the status of the Measurement Report to &quot;Approved&quot; and subsequently confirming it in the verification report.</p></li></ul><p>The Client Representative can also edit the quantity or price in the Invoiced Quantity or Invoiced Price column. This operation changes the item status to &quot;Change&quot;. Such an item is considered &quot;approved with changes&quot; and is therefore considered resolved.</p><p>If the user sets the Invoiced Quantity or price of an item to zero, its status changes to &quot;Rejected&quot;. Conversely, changing the status to &quot;Rejected&quot; sets the Invoiced Quantity and price to zero. Such items are also considered resolved for the purposes of the approval process.</p><img src="'+n+'" alt="" width="1200" loading="lazy"><p>If the Client Representative considers all items resolved, they change the status of the Measurement Report using the Approve button.</p><figure class="shot" style="--w:250px;"><img src="'+a+'" alt="" width="250" loading="lazy"></figure><p>If the contractor needs to make changes to some items, the Client Representative changes the status of the Measurement Report to &quot;Return for Correction&quot;. When the status is changed in this way, items with the &quot;Draft&quot; status are changed to &quot;In Negotiation&quot;.</p><h2 id="proposal-change" tabindex="-1">Proposal Change <a class="header-anchor" href="#proposal-change" aria-label="Permalink to &quot;Proposal Change&quot;">​</a></h2><p>If the Measurement Report is in the &quot;Proposal Change&quot; status, the contractor can edit the &quot;Changed Quantity&quot; column only for items that have the &quot;In Negotiation&quot; status or for items for which no &quot;Proposed Quantity&quot; has yet been entered.</p><img src="'+r+'" alt="" width="1200" loading="lazy"><p>After entering the changes, the contractor submits the Measurement Report to the Client Representative for approval again.</p>',24)])])}const b=s(p,[["render",h]]);export{_ as __pageData,b as default};
